{"label": "95d20143d5e2af5612b1", "speaker_changes_inside": "no", "view": "own_sincere", "referents": [{"word": "I", "refers_to": "the guest (Michael Dunworth)", "inside": true, "changes_assertion": "no"}, {"word": "you", "refers_to": "the host, the betting counterpart", "inside": false, "changes_assertion": "no"}], "conditions": [{"text": "RSA broken in 10 years (one Bitcoin) or in five years (half a Bitcoin)", "inside": true}], "retraction": "none", "time_ok": "yes", "proposition": "The speaker is so convinced RSA will be broken by AI-era progress that he offers bets: one Bitcoin it breaks within 10 years, half a Bitcoin within five.", "certainty": "likely", "speaker_is": "guest", "speaker_evidence": "You were you were the uh cryptography is going to break guy before it was cool"},
{"label": "b799cf6a63d3a47d7d9d", "speaker_changes_inside": "no", "view": "own_sincere", "referents": [{"word": "it", "refers_to": "Bitcoin", "inside": true, "changes_assertion": "no"}, {"word": "that", "refers_to": "technology (asteroid mining) doubling the gold supply and invalidating scarcity", "inside": false, "changes_assertion": "yes"}], "conditions": [], "retraction": "none", "time_ok": "yes", "proposition": "Bitcoin, unlike gold, is immune to a technology-driven supply shock because no asteroid will ever yield more Bitcoin.", "certainty": "certain", "speaker_is": "guest", "speaker_evidence": "Why Bitcoin CANNOT Reach $1 Million by 2030 | Haseeb Qureshi"},
{"label": "a45d26b88cd5b176ae13", "speaker_changes_inside": "no", "view": "own_sincere", "referents": [{"word": "I", "refers_to": "Phong Le, CEO of Strategy", "inside": true, "changes_assertion": "no"}, {"word": "we", "refers_to": "the industry / financial markets broadly (generic)", "inside": true, "changes_assertion": "no"}], "conditions": [], "retraction": "none", "time_ok": "yes", "proposition": "Bitcoin and crypto are not partisan issues; they are about modernizing financial markets and creating financial freedom for Americans and the world.", "certainty": "likely", "speaker_is": "guest", "speaker_evidence": "FENG LI, CEO OF STRATEGY. IT'S GREAT TO SEE YOU TODAY"},
