{"label": "44216aab8847bd718241", "speaker_changes_inside": "no", "view": "own_sincere", "referents": [{"word": "its", "refers_to": "Strategy's Bitcoin", "inside": true, "changes_assertion": "no"}], "conditions": [], "retraction": "none", "time_ok": "yes", "proposition": "The MSCI-related selling affects only Strategy's shares; the funds' selling never touches Strategy's Bitcoin, which MSCI's decision does not force it to sell.", "certainty": "certain", "speaker_is": "host", "speaker_evidence": ""},
